{
  "version": "1",
  "text": "Your navy top with its sheer, structured neckline feels effortless and modern against your skin, grounding the look instantly. The straight-leg jeans in a deep blue shade elongate your vertical line while keeping the lower half quiet and balanced. The burnt-orange bag offers just enough pop to draw attention upward without overwhelming your silhouette. A classic wool coat closes off with rich, warm tones that carry you from evening to later hours, softening edges and adding depth.",
  "how_to_wear": [
    "Wear the coat open if you're dancing late — it keeps your layers light while keeping warmth near your shoulders.",
    "Tuck the top slightly at the front for a subtle waist cue without tightening anything."
  ],
  "wrong_photos": [],
  "swap": {},
  "about_items": [
    {
      "n": "#163·31",
      "text": "A navy ribbed knit top with sheer mesh panels across the upper chest and shoulders, long sleeves that drape smoothly over your arms. The semi-transparent detailing adds a modern touch without revealing too much — perfect for an evening setting that demands subtle allure."
    },
    {
      "n": "#47·32",
      "text": "High-waisted straight-leg jeans in a rich, mid-to-dark denim wash with a visible double-stitched waistband. They fall just above the ankle, offering clean lines that complement the longer silhouette of your top and coat."
    },
    {
      "n": "#360·03",
      "text": "A structured orange leather bag with a top handle and dual zippered compartments. Its slightly boxy shape and polished finish make it an eye-catching accessory that stands out without overwhelming the outfit."
    },
    {
      "n": "#125·07",
      "text": "Soft suede loafers in warm brown tones, finished with a decorative tassel on the vamp. Their flat profile and relaxed fit offer comfort for dancing while adding a polished yet easygoing edge."
    },
    {
      "n": "#37·04",
      "text": "A tailored wool coat in deep brown, double-breasted with large matte buttons and classic lapels. The fabric drapes fluidly over your frame, offering warmth and sophistication without clinging to the waist."
    }
  ]
}
